// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

// Migrations take a Postgres advisory lock, which a transaction-pooled endpoint
// (pgnest :6432) cannot hold, so `migrate deploy` hangs with P1002. Use the
// direct/session endpoint (:6433) via DIRECT_URL; the app runtime keeps using
// the pooled DATABASE_URL through the pg adapter.
const url = process.env.DIRECT_URL || process.env.DATABASE_URL;

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: url as string,
  },
});
